-- Gallery: database mirror of app/content/gallery.generated.json.
-- Files live in the `portfolio-media` bucket under gallery/<series>/<photo>/.
-- Ids are generated by the import script and shared with the JSON store.

create table public.gallery_series (
  id uuid primary key,

  slug text not null unique,

  -- Set after the photos exist; see gallery_series_cover_fk below.
  cover_photo_id uuid,

  sort_order integer not null default 0,
  published boolean not null default false,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);


create table public.gallery_series_translations (
  series_id uuid not null
    references public.gallery_series(id)
    on delete cascade,

  locale text not null
    check (locale in ('en', 'ja')),

  title text not null,
  description text,

  primary key (series_id, locale)
);


create table public.gallery_photos (
  id uuid primary key,

  series_id uuid not null
    references public.gallery_series(id)
    on delete cascade,

  slug text not null,

  -- gallery/<series>/<photo>/<hash>; files are <storage_path>-<size>.<avif|webp>
  storage_path text not null
    check (storage_path ~ '^gallery/[a-z0-9-]+/[a-z0-9-]+/[0-9a-f]{8}$'),

  width integer not null check (width > 0),
  height integer not null check (height > 0),

  blur_data_url text not null,
  dominant_color text not null,

  -- Camera-local time from EXIF; no zone is known.
  taken_at timestamp,
  camera text,
  lens text,

  aperture numeric,
  shutter numeric,
  iso integer,
  focal_length numeric,

  featured boolean not null default false,
  sort_order integer not null default 0,
  published boolean not null default false,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  unique (series_id, slug)
);


create table public.gallery_photo_translations (
  photo_id uuid not null
    references public.gallery_photos(id)
    on delete cascade,

  locale text not null
    check (locale in ('en', 'ja')),

  -- Empty until written; a photo is only published once both locales have it.
  alt text not null default '',
  title text,
  place text,

  primary key (photo_id, locale)
);


alter table public.gallery_series
  add constraint gallery_series_cover_fk
  foreign key (cover_photo_id)
  references public.gallery_photos(id)
  on delete set null;

create index gallery_photos_series_order
on public.gallery_photos(series_id, sort_order);


-- Row level security: the public reads published rows; admins write.

alter table public.gallery_series enable row level security;
alter table public.gallery_series_translations enable row level security;
alter table public.gallery_photos enable row level security;
alter table public.gallery_photo_translations enable row level security;

create policy "public reads published series"
on public.gallery_series
for select
to anon, authenticated
using (published);

create policy "public reads translations of published series"
on public.gallery_series_translations
for select
to anon, authenticated
using (exists (
  select 1 from public.gallery_series s
  where s.id = series_id and s.published
));

create policy "public reads published photos"
on public.gallery_photos
for select
to anon, authenticated
using (published and exists (
  select 1 from public.gallery_series s
  where s.id = series_id and s.published
));

create policy "public reads translations of published photos"
on public.gallery_photo_translations
for select
to anon, authenticated
using (exists (
  select 1 from public.gallery_photos p
  where p.id = photo_id and p.published
));

create policy "admins manage series"
on public.gallery_series
for all
to authenticated
using ((select public.is_admin()))
with check ((select public.is_admin()));

create policy "admins manage series translations"
on public.gallery_series_translations
for all
to authenticated
using ((select public.is_admin()))
with check ((select public.is_admin()));

create policy "admins manage photos"
on public.gallery_photos
for all
to authenticated
using ((select public.is_admin()))
with check ((select public.is_admin()));

create policy "admins manage photo translations"
on public.gallery_photo_translations
for all
to authenticated
using ((select public.is_admin()))
with check ((select public.is_admin()));
